class Expense {
  Expense(this.id,this.title,this.category,this.amount,this.date,{this.note='',this.splitMode='',this.shares=const []});
  String id,title,category,note,splitMode; double amount; DateTime date; List<Map<String,dynamic>> shares;
  Map<String,dynamic> json()=>{'id':id,'title':title,'category':category,'amount':amount,'date':date.toIso8601String(),'note':note,'splitMode':splitMode,'shares':shares};
  factory Expense.from(Map<String,dynamic> j)=>Expense(j['id']??'',j['title']??'',j['category']??'Other',(j['amount'] as num).toDouble(),DateTime.tryParse(j['date']??'')??DateTime.now(),note:j['note']??'',splitMode:j['splitMode']??'',shares:List<Map<String,dynamic>>.from((j['shares']??[]).map((e)=>Map<String,dynamic>.from(e))));
}
